.aprilfool2026-pfImage {
position:absolute;
animation: aprilfool2026-pfImage 100s;
animation-timing-function:ease-out;
animation-fill-mode:forwards;
}
@keyframes aprilfool2026-pfImage
{
0% {z-index:-41;opacity: 1;}
0.5% {z-index:41;opacity: 1;}
100% {z-index:41;opacity: 0;}
}
#aprilfool2026-stage4Div {
position: fixed;
left: 0;
top: 30vh;
width: 100vw;
text-align: center;
z-index: 41;
font-size: 5vw;
font-weight: bold;
color: white;
animation: aprilfool2026-stage4Div 10s;
animation-timing-function:ease-in-out;
animation-fill-mode:forwards;
}
@keyframes aprilfool2026-stage4Div
{
0% {z-index:41;opacity: 0;}
50% {z-index:41;opacity: 1;}
100% {z-index:41;opacity: 0;}
}
.aprilfool2026-stageDiv {
animation: aprilfool2026-stageDiv 1s;
animation-timing-function:ease-out;
animation-fill-mode:forwards;
}
@keyframes aprilfool2026-stageDiv
{
0% {z-index:41;opacity: 0;}
100% {z-index:41;opacity: 1;}
}
.aprilfool2026-fallenImage {
position:absolute;
animation: aprilfool2026-fallenImage 1s;
animation-timing-function:ease-out;
animation-fill-mode:forwards;
}
@keyframes aprilfool2026-fallenImage
{
0% {z-index:41;top:0;opacity:1;}
100% {z-index:41;top:1000px;opacity: 0;}
}
.aprilfool2026-body .gt-label-box-link,
.aprilfool2026-body .bigger-inner-link{
display:none;
}
.aprilfool2026-body {
/* https://github.com/GTNewHorizons/GT5-Unofficial/blob/master/src/main/resources/assets/gregtech/textures/items/gt.Tool_Vajra.png */
cursor: url("data:image/png;base64,"), auto;
}
.powerfailImage {
width: 64px;
height: 64px;
overflow: hidden;
}
.powerfailImage img {
position: absolute;
animation: powerfailImage 2s infinite;
top: -64px;
}
@keyframes powerfailImage
{
0% {top: -64px;}
49.99% {top: -64px;}
50% {top: 0px;}
}
