mw.hook('wikipage.content').add(function ($content) {
$content.find('.lua-smart-form').each(function () {
var $formContainer = $(this);
if ($formContainer.data('initialized')) return;
var moduleName = $formContainer.attr('data-module');
var funcName = $formContainer.attr('data-function');
var api = new mw.Api();
var timeout = null;
var controls = {};
var customGetValue = null;
// --- 0. 模糊匹配评分（用于 search 控件） ---
var fuzzyScore = function (query, text) {
var q = (query || '').toLowerCase();
var t = (text || '').toLowerCase();
if (!q) return 1;
if (q === t) return 1000;
if (t.indexOf(q) === 0) return 500;
if (t.indexOf(q) > 0) return 300;
var qi = 0, score = 0, consec = 0;
for (var ti = 0; ti < t.length && qi < q.length; ti++) {
if (t[ti] === q[qi]) {
qi++;
consec++;
score += consec * 10;
} else {
consec = 0;
}
}
return qi === q.length ? score : -1;
};
// --- 1. 就地解析所有的 form-config 节点 ---
// --- 0.1 search / search-list 控件：白色小卡片 + 编辑/删除/添加按钮 ---
var SEARCH_ICON = {
edit: '<i class="fa fa-pencil" aria-hidden="true"></i>',
remove: '<i class="fa fa-trash" aria-hidden="true"></i>',
add: '<i class="fa fa-plus" aria-hidden="true"></i>'
};
// 候选统一成 { value, label }
var normalizeSearchOptions = function (options) {
return (options || []).map(function (opt) {
if (opt && typeof opt === 'object' && opt.value !== undefined) {
return { value: opt.value, label: String(opt.label !== undefined ? opt.label : opt.value) };
}
return { value: opt, label: String(opt) };
});
};
var searchLabelOf = function (options, value) {
for (var i = 0; i < options.length; i++) {
if (String(options[i].value) === String(value)) return options[i].label;
}
return (value === undefined || value === null) ? '' : String(value);
};
// 输入文本 → 候选值（显示名和值都接受）
var searchMatchOf = function (options, text) {
for (var i = 0; i < options.length; i++) {
if (String(options[i].value) === String(text) || String(options[i].label) === String(text)) {
return { value: options[i].value, label: options[i].label, matched: true };
}
}
return { value: text, label: text, matched: false };
};
// 单个搜索卡片：只读态显示已选值，编辑态显示文本框和候选下拉
var createSearchCard = function (config, options, initialValue, cardOpts) {
cardOpts = cardOpts || {};
var value = initialValue;
var $card = $('<div class="search-card"></div>');
var $view = $('<span class="search-view"></span>');
var $label = $('<span class="search-selected-label"></span>').text(searchLabelOf(options, value));
var $editBtn = $('<button type="button" class="search-edit-btn" title="编辑"></button>').html(SEARCH_ICON.edit);
var $input = $('<input type="text" class="search-input-text">')
.attr('placeholder', config.placeholder || '输入搜索...');
var $dropdown = $('<div class="search-dropdown"></div>');
var $editWrap = $('<span class="search-edit-wrap"></span>').append($input, $dropdown);
$view.append($label);
$card.append($view, $editWrap, $editBtn);
var card = {
$el: $card,
input: $input,
getValue: function () { return value; },
hasValue: function () { return value !== undefined && value !== null && String(value) !== ''; },
setValue: function (v) { value = v; $label.text(searchLabelOf(options, v)); },
edit: function () { enterEdit(); }
};
if (cardOpts.removable) {
var $delBtn = $('<button type="button" class="search-del-btn" title="删除"></button>').html(SEARCH_ICON.remove);
$card.append($delBtn);
$delBtn.on('click', function () {
if (cardOpts.onRemove) cardOpts.onRemove(card);
});
}
var renderOptions = function (filterText) {
$dropdown.empty();
var candidates = [];
options.forEach(function (o) {
var score = fuzzyScore(filterText || '', o.label);
if (score >= 0) candidates.push({ opt: o, score: score });
});
candidates.sort(function (a, b) { return b.score - a.score; });
candidates.forEach(function (c) {
var $item = $('<div class="search-dropdown-item"></div>').text(c.opt.label);
$item.on('mousedown', function (e) {
e.preventDefault(); // 防止 blur 先隐藏下拉
commit(c.opt.value);
});
$dropdown.append($item);
});
if (candidates.length > 0) $dropdown.show(); else $dropdown.hide();
};
var commit = function (v) {
card.setValue(v);
$input.val(String(v === undefined || v === null ? '' : v));
$dropdown.hide();
$card.removeClass('is-editing');
if (cardOpts.onCommit) cardOpts.onCommit(card);
};
var enterEdit = function () {
$card.addClass('is-editing');
$input.val(searchLabelOf(options, value));
$input.focus();
$input.select();
renderOptions($input.val());
};
$editBtn.on('click', enterEdit);
var searchDebounce = null;
$input.on('input', function () {
clearTimeout(searchDebounce);
searchDebounce = setTimeout(function () {
renderOptions($input.val());
}, 150);
});
$input.on('blur', function () {
setTimeout(function () {
$dropdown.hide();
var typed = $.trim($input.val());
var hit = searchMatchOf(options, typed);
if (hit.matched) {
var changed = String(hit.value) !== String(value === undefined || value === null ? '' : value);
card.setValue(hit.value);
$input.val(String(hit.value));
$card.removeClass('is-editing');
if (changed && cardOpts.onCommit) {
cardOpts.onCommit(card);
}
} else {
// 未匹配：回到已选值；新增的空卡片交给调用方处理
$card.removeClass('is-editing');
if (!card.hasValue() && cardOpts.onCancel) {
cardOpts.onCancel(card);
}
}
}, 200);
});
return card;
};
$formContainer.find('.form-config').each(function () {
var $configDiv = $(this);
var f;
try {
f = JSON.parse($configDiv.text().trim());
} catch (e) {
$configDiv.html('<span style="color:red;">JSON错误</span>');
return;
}
var $input;
var $wrapper = $('<div class="smart-input-wrapper" style="margin: 5px 0;"></div>');
if (f.label) $wrapper.append($('<label style="font-weight:bold; margin-right:8px;"></label>').text(f.label));
switch (f.type) {
case 'number':
$input = $('<input type="number" style="width:120px;padding:4px; border:1px solid #ccc;">')
.attr({
min: (f.min !== undefined) ? f.min : false,
max: (f.max !== undefined) ? f.max : false,
step: f.integer ? 1 : (f.step || 'any')
})
.val(f.default !== undefined ? f.default : 0);
break;
case 'select':
$input = $('<select style="padding:4px;">');
(f.options || []).forEach(function (opt) {
if (typeof opt === 'object' && opt.value !== undefined) {
$input.append($('<option>').val(opt.value).text(opt.label || opt.value));
} else {
$input.append($('<option>').val(opt).text(opt));
}
});
$input.val(f.default);
break;
case 'search':
var singleOptions = normalizeSearchOptions(f.options);
var singleCard = createSearchCard(f, singleOptions, f.default, {
removable: false,
onCommit: function () { runLua(); }
});
$input = singleCard.input;
customGetValue = function () { return singleCard.getValue(); };
$wrapper.append(singleCard.$el);
break;
case 'search-list':
var listOptions = normalizeSearchOptions(f.options);
var listDefaults = (f.default === undefined || f.default === null) ? []
: ($.isArray(f.default) ? f.default : [f.default]);
var $listWrap = $('<div class="search-list-wrap"></div>');
var $emptyHint = $('<span class="search-list-empty">尚未添加，点击 + 添加一项</span>');
var $list = $('<div class="search-list"></div>');
var $addBtn = $('<button type="button" class="search-add-btn" title="添加一项"></button>').html(SEARCH_ICON.add);
var listCards = [];
var updateListState = function () {
$emptyHint.toggleClass('is-empty-hidden', listCards.length > 0);
// 新增的空白卡片填入非空值之前先藏起加号，避免同时出现多张空白卡片
var hasPending = listCards.some(function (c) { return !c.hasValue(); });
if (hasPending) $addBtn.hide(); else $addBtn.show();
};
var removeListCard = function (card) {
var idx = listCards.indexOf(card);
if (idx >= 0) listCards.splice(idx, 1);
card.$el.remove();
updateListState();
};
var addListCard = function (val, isNew) {
var card = createSearchCard(f, listOptions, val, {
removable: true,
onCommit: function (c) {
var v = c.getValue();
var duplicated = listCards.some(function (other) {
return other !== c && String(other.getValue()) === String(v);
});
if (duplicated) {
if (isNew) {
removeListCard(c);
} else {
c.setValue(val);
}
alert('「' + searchLabelOf(listOptions, v) + '」已经在列表里了');
return;
}
isNew = false;
updateListState();
runLua();
},
onRemove: function (c) {
removeListCard(c);
runLua();
},
onCancel: function (c) {
if (isNew) removeListCard(c);
}
});
listCards.push(card);
$addBtn.before(card.$el);
updateListState();
return card;
};
$list.append($addBtn);
