(function () {
"use strict";
var STORAGE_KEY = "gtnh-color-scheme";
var FORCED_DARK_STYLE_ID = "gtnh-color-scheme-forced-dark";
var OPEN_CLASS = "is-open";
var forcedDarkPromise = null;
var systemDarkQuery = window.matchMedia ? window.matchMedia("(prefers-color-scheme: dark)") : null;
var MODES = [
{ id: "eye", label: "护眼", icon: "fa-eye" },
{ id: "light", label: "浅色", icon: "fa-sun-o" },
{ id: "dark", label: "深色", icon: "fa-moon-o" },
{ id: "system", label: "系统", icon: "fa-desktop" }
];
function getMode(id) {
for (var i = 0; i < MODES.length; i++) {
if (MODES[i].id === id) return MODES[i];
}
return MODES[MODES.length - 1];
}
function isKnownMode(mode) {
return mode === "eye" || mode === "light" || mode === "dark" || mode === "system";
}
function readMode() {
try {
var saved = localStorage.getItem(STORAGE_KEY);
if (saved === "light" || saved === "dark" || saved === "system") return saved;
return saved === "eye" ? saved : "system";
} catch (e) {
return "system";
}
}
function writeMode(mode) {
try {
localStorage.setItem(STORAGE_KEY, mode);
} catch (e) {}
}
function isSystemDark() {
return !!(systemDarkQuery && systemDarkQuery.matches);
}
function resolveMode(mode) {
if (mode === "system") {
return isSystemDark() ? "dark" : "eye";
}
return mode;
}
function getColorSchemeCssUrl() {
if (window.mw && mw.util && typeof mw.util.getUrl === "function") {
return mw.util.getUrl("零件:ColorScheme.css", {
action: "raw",
ctype: "text/css"
});
}
return "/wiki/零件:ColorScheme.css?action=raw&ctype=text/css";
}
function extractDarkMedia(css) {
var text = css.replace(/^\s*\/\*[\s\S]*?\*\/\s*/, "").trim();
var prefix = "@media (prefers-color-scheme: dark)";
var start = text.indexOf(prefix);
if (start === -1) return text;
var open = text.indexOf("{", start + prefix.length);
if (open === -1) return text;
var depth = 0;
var quote = "";
var escaped = false;
for (var i = open; i < text.length; i++) {
var ch = text.charAt(i);
if (quote) {
if (escaped) {
escaped = false;
} else if (ch === "\\") {
escaped = true;
} else if (ch === quote) {
quote = "";
}
continue;
}
if (ch === '"' || ch === "'") {
quote = ch;
continue;
}
if (ch === "{") depth++;
if (ch === "}") {
depth--;
if (depth === 0) {
return text.slice(open + 1, i);
}
}
}
return text;
}
function buildForcedDarkCss(css) {
return extractDarkMedia(css)
.replace(
/html:not\(\[data-gtnh-color-scheme="eye"\]\):not\(\[data-gtnh-color-scheme="light"\]\)/g,
'html[data-gtnh-color-scheme="dark"]'
)
.replace(
/html:not\(\[data-gtnh-color-scheme="light"\]\)/g,
'html[data-gtnh-color-scheme="dark"]'
);
}
function ensureForcedDarkCss() {
if (document.getElementById(FORCED_DARK_STYLE_ID) || isSystemDark()) return;
if (forcedDarkPromise) return;
forcedDarkPromise = fetch(getColorSchemeCssUrl(), { credentials: "same-origin" })
.then(function (response) {
if (!response.ok) throw new Error("ColorScheme.css load failed");
return response.text();
})
.then(function (css) {
if (document.getElementById(FORCED_DARK_STYLE_ID)) return;
var style = document.createElement("style");
style.id = FORCED_DARK_STYLE_ID;
style.textContent = buildForcedDarkCss(css);
document.head.appendChild(style);
})
.catch(function () {
forcedDarkPromise = null;
});
}
function updateSwitcher(mode, resolvedMode) {
var switcher = document.querySelector(".gtnh-color-switcher");
if (!switcher) return;
var activeMode = getMode(mode);
var trigger = switcher.querySelector(".gtnh-color-switcher-trigger");
if (trigger) {
trigger.innerHTML =
'<i class="fa ' +
activeMode.icon +
'" aria-hidden="true"></i><span>' +
activeMode.label +
'</span><i class="fa fa-caret-down" aria-hidden="true"></i>';
trigger.setAttribute("aria-label", "配色模式：" + activeMode.label);
trigger.setAttribute("title", "");
