var options = switcher.querySelectorAll(".gtnh-color-switcher-option");
for (var i = 0; i < options.length; i++) {
var active = options[i].getAttribute("data-mode") === mode;
options[i].classList.toggle("is-active", active);
options[i].setAttribute("aria-pressed", active ? "true" : "false");
}
switcher.setAttribute("data-active-mode", mode);
switcher.setAttribute("data-resolved-mode", resolvedMode);
