function applyMode(mode) {
if (!isKnownMode(mode)) mode = "system";
var resolvedMode = resolveMode(mode);
document.documentElement.setAttribute("data-gtnh-color-scheme-mode", mode);
document.documentElement.setAttribute("data-gtnh-color-scheme", resolvedMode);
updateSwitcher(mode, resolvedMode);
if (resolvedMode === "dark" && !isSystemDark()) ensureForcedDarkCss();
}
function closeSwitcher() {
var switcher = document.querySelector(".gtnh-color-switcher");
if (!switcher) return;
switcher.classList.remove(OPEN_CLASS);
var trigger = switcher.querySelector(".gtnh-color-switcher-trigger");
