: px[0] + NODE_OFFSET_X;
var y = (px[1] + NODE_OFFSET_Y + th > ch)
? px[1] - th - NODE_OFFSET_Y
: px[1] + NODE_OFFSET_Y;
if (x < 0) x = 0;
