<div

.lpb-container {
width: 100%;
padding: 8px 0;
}
.lpb-row {
display: grid;
grid-template-columns: auto 1fr auto;
gap: 8px;
align-items: center;
margin-bottom: 4px;
}
.lpb-label {
font-size: 13px;
font-weight: bold;
color: #000;
text-align: right;
}
.lpb-bar {
height: 26px;
background: #e8e8e8;
border-radius: 4px;
overflow: hidden;
position: relative;
}
.lpb-bar-empty {
height: 26px;
}
.lpb-bar-fill {
height: 100%;
border-radius: 4px;
transition: width 0.6s ease;
position: relative;
}
.lpb-translated .lpb-bar-fill { background: #3B77FE; }
.lpb-checked .lpb-bar-fill { background: #2FC997; }
.lpb-reviewed .lpb-bar-fill { background: #2AA746; }
.lpb-articles .lpb-bar-fill { background: #f0ad4e; }
.lpb-edits .lpb-bar-fill { background: #5bc0de; }
.lpb-followers .lpb-bar-fill { background: #5cb85c; }
.lpb-bar-fill.lpb-striped {
background-image: linear-gradient(
45deg,
rgba(255,255,255,.15) 25%,
transparent 25%,
transparent 50%,
rgba(255,255,255,.15) 50%,
rgba(255,255,255,.15) 75%,
transparent 75%,
transparent
);
background-size: 40px 40px;
}
.lpb-bar-fill.lpb-striped.lpb-active {
animation: lpb-stripe-anim 2s linear infinite;
}
@keyframes lpb-stripe-anim {
from { background-position: 40px 0; }
to { background-position: 0 0; }
}
.lpb-bar-pct {
display: block;
line-height: 26px;
text-align: center;
color: #fff;
font-size: 12px;
font-weight: bold;
text-shadow: 0 0 4px rgba(0, 0, 0, 0.6);
white-space: nowrap;
}
.lpb-stat {
font-size: 13px;
color: #000;
text-align: right;
min-width: 60px;
}
.lpb-grid {
display: grid;
grid-template-columns: auto 1fr auto;
gap: 4px 8px;
align-items: center;
}
.lpb-grid > .lpb-bar {
margin: 0;
}
.lpb-stat-cur { color: #3B77FE; }
.lpb-stat-div { color: #bbb; margin: 0 2px; }
.lpb-stat-tgt { color: #999; }
.lpb-loading,
.lpb-error {
padding: 6px 0;
font-size: 13px;
}
.lpb-error {
color: #d33;
}
