<div

/* 变量输入框的大背景 */
.mathjax-follower-bg{
text-align: right;
position: absolute;
padding:4px 8px;
background-color: rgb(251 251 251 / 100%);
border-radius:4px;
border:solid 1px #adadad;
color:black;
white-space:nowrap; /* 避免自动换行 */
}
/* Fx按钮 隐藏全部按钮 关闭悬浮框按钮*/
.follower-drag-and-drop{
padding:0;
}
.follower-drag-and-drop > .fa-arrows{
cursor:move;
}
.follower-echart-show{
padding:0;
}
.follower-hide-all{
padding:0;
}
.follower-hide{
padding:0;
}
/* 悬浮窗中的echart图像背景 */
.mathjax-follower-echart{
width:400px;
height:200px;
}
/* 变量输入框最外框 */
.mathvar-hint{
white-space:nowrap;
}
/* 变量输入框 条框 */
.mathvar-input-container{
display: inline-block;
width: 120px;
height: 30px;
position: relative;
background-color: rgb(243, 243, 243);
border-radius: 8px;
margin: 0px 2px;
user-select: none;
vertical-align:middle;
/* border:solid 1px #cfcfcf; */
}
/* 变量输入框 公式部分 */
.mathvar-text{
position: absolute; bottom: 2px; left: 6px; user-select: none;
}
/* 变量输入框 百分比条 */
.mathvar-percent {
