}
/* 变量输入框 点击判定元素 */
.mathvar-click{
position: absolute; inset: 0px;
}
/* 变量输入框 加锁解锁帮助按钮 */
.mathvar-lock-btn{
padding:0;width:12px;
}
.mathvar-lock-btn > .fa-unlock {
color:gray;
}
.mathvar-lock-btn > .fa-lock {
color:black;
}
.mathvar-help-btn{
padding:0;width:8px;
}
.mathvar-help-btn > .fa-question-circle-o {
color:gray;
}
