window.GTNH = window.GTNH || {};
window.GTNH.ProcessingLogic = (function() {
var voltageTiers = ["ULV", "LV", "MV", "HV", "EV", "IV", "LuV", "ZPM", "UV", "UHV", "UEV", "UIV", "UMV", "UXV", "MAX"];
/**
* 1. 电压值 -> 电压等级序数 (Tier Index)
* ULV 是特例(8V)，其余符合 32 * 4^(n-1)
*/
var getTierFromVoltage = function(v) {
if (v <= 8) return 0; // ULV
if (v <= 32) return 1; // LV
// 使用换底公式: log4(x) = ln(x) / ln(4)
// 加上 1e-9 的微小偏移量防止浮点数精度问题导致 floor 出错
var tier = Math.floor(Math.log(v / 8) / Math.log(4) - 1e-7) + 1;
return Math.max(0, tier);
};
/**
* 2. 电压等级序数 -> 电压值 (Voltage)
*/
var getVoltageFromTier = function(t) {
if (t <= 0) return 8; // ULV
// 32 * 4^(t-1)
return 32 * Math.pow(4, t - 1);
};
/**
* 3. 电压等级序数 -> 电压等级字符串
*/
var getNameFromTier = function(t) {
if (t >= 0 && t < voltageTiers.length) {
return voltageTiers[t];
}
return "MAX+" + (t - voltageTiers.length + 1);
};
/**
* 4. 电压等级字符串 -> 电压等级序数
*/
var getTierFromName = function(name) {
if (!name) return -1;
var upperName = name.toUpperCase();
for (var i = 0; i < voltageTiers.length; i++) {
if (voltageTiers[i].toUpperCase() === upperName) {
return i;
}
}
return -1;
};
var getRecommendedAmperages = function(voltageName) {
var tierIdx = getTierFromVoltage(voltageName);
var result = [];
var value = 1;
// LV 开始给 1，MV 给 1,4，HV 给 1,4,16 ...
// tierIdx <= 1 时只给 1
var count = Math.max(1, tierIdx);
for (var i = 0; i < count; i++) {
result.push(value);
value *= 4;
}
return result;
};
/**
* 在对象中查找第一个匹配指定值的键
* @param {Object} obj - 要查询的字典/对象
* @param {*} v - 要查找的目标值
* @returns {String|null} - 返回找到的第一个键名，未找到则返回 null
*/
var findKeyByValue = function(obj, v) {
// 基础防错：确保输入的是对象且不是 null
if (!obj || typeof obj !== 'object') {
return null;
}
// 使用 for...in 遍历
for (var key in obj) {
// 关键：只检查对象自身的属性，忽略原型链上的属性
if (Object.prototype.hasOwnProperty.call(obj, key)) {
// 使用全等比较 (===)
if (obj[key] === v) {
return key;
}
}
}
return null;
};
