/**
* RandomBackground
* @author 机智的小鱼君
* @license MIT
*/
/**
* @typedef {{
* src: string;
* description?: string;
* }} BgConfigListItem
*
* @typedef {{
* list: BgConfigListItem[];
* [k: string]: any;
* }} BgConfigPageData
*/
window.RLQ = window.RLQ || []
window.RLQ.push([
['mediawiki.Title'],
function () {
var CACHE_KEY = 'NGNL:RandomBackgroundList'
var CACHE_TTL = 24 * 60 * 60 * 1000
var LIST_TITLE = new mw.Title('RandomBackgroundList.json', 4)
/** @type {<T>(list: T[]) => T} */
function randomPick(list) {
return list[Math.floor(Math.random() * list.length)]
}
/**
* @returns {Promise<BgConfigListItem[]>}
*/
function fetchBgList() {
var cache = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null')
// 24 hours
if (cache && Date.now() - cache.time < CACHE_TTL) {
return Promise.resolve(cache.data)
}
return fetch(
LIST_TITLE.getUrl({ action: 'raw', ctype: 'application/json' })
)
.then(function (resp) {
return resp.json()
})
.then(
/**
* @param {BgConfigPageData} body
*/
function (body) {
if (
typeof body === 'object' &&
body !== null &&
Array.isArray(body.list) &&
body.list.length > 0
) {
localStorage.setItem(
CACHE_KEY,
JSON.stringify({
time: Date.now(),
data: body.list,
})
)
return body.list
}
throw new Error('Invalid background list')
}
)
}
/**
* @param {BgConfigListItem[]} list
* @param {string?} current
*/
function setRandomBg(list, current) {
var filteredUrls = Array.from(
new Set(
list.map(function (item) {
return item.src
})
)
).filter(function (url) {
return typeof url === 'string' && url !== '' && url !== current
})
if (filteredUrls.length === 0) {
return null
}
var url = randomPick(filteredUrls)
if (url) {
document.documentElement.style.setProperty(
'--theme-custom-background-image',
'url(' + url + ')'
)
}
return url
}
/**
* @returns {HTMLElement}
*/
function makeRandomButton() {
/** @type {HTMLElement} */
var btn = document
.querySelector('.skin-subnav-wrapper .n-button')
.cloneNode(true)
/** @type {HTMLElement} */
var content = btn.querySelector('.n-button__content')
btn.removeAttribute('href')
content.textContent = '随机背景'
/** @type {HTMLElement} */
var icon =
btn.querySelector('.n-button__icon') || document.createElement('i')
/** @type {string} */
icon.classList.add('n-icon', 'n-icon-random')
icon.innerHTML =
'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 512 512"><path d="M504.971 359.029c9.373 9.373 9.373 24.569 0 33.941l-80 79.984c-15.01 15.01-40.971 4.49-40.971-16.971V416h-58.785a12.004 12.004 0 0 1-8.773-3.812l-70.556-75.596l53.333-57.143L352 336h32v-39.981c0-21.438 25.943-31.998 40.971-16.971l80 79.981zM12 176h84l52.781 56.551l53.333-57.143l-70.556-75.596A11.999 11.999 0 0 0 122.785 96H12c-6.627 0-12 5.373-12 12v56c0 6.627 5.373 12 12 12zm372 0v39.984c0 21.46 25.961 31.98 40.971 16.971l80-79.984c9.373-9.373 9.373-24.569 0-33.941l-80-79.981C409.943 24.021 384 34.582 384 56.019V96h-58.785a12.004 12.004 0 0 0-8.773 3.812L96 336H12c-6.627 0-12 5.373-12 12v56c0 6.627 5.373 12 12 12h110.785c3.326 0 6.503-1.381 8.773-3.812L352 176h32z" fill="currentColor"></path></svg>' // fa fas-random
content.insertAdjacentElement('afterbegin', icon)
return btn
}
// main
fetchBgList()
.then(function (list) {
var current = setRandomBg(list)
document.body.classList.add('random-background-applied')
var wrapper = document.querySelector('.skin-subnav-wrapper')
if (wrapper) {
var button = makeRandomButton()
wrapper.appendChild(button)
button.addEventListener('click', function (e) {
e.preventDefault()
current = setRandomBg(list, current)
})
}
})
.catch(function (err) {
console.error('[Random Background]', err)
})
},
])
