/**
* GTNH 产线矩阵计算器 (RecipeCalculator.js)
* 支持多实例共存、独立机器动力学解耦、全局智能联锁高亮、模板挂载
* 动态工艺分支系统 + 自动前置后置闭环计算边界 (Dynamic Auto-Env)
* 纯 ES5 语法，适配 MediaWiki
*/
var MathEngine = {
solveLinearSystem: function (matrix, constants) {
var n = matrix.length;
if (n === 0) return [];
var cols = matrix[0].length;
// 构建增广矩阵 [A | b]
var m = [];
for (var i = 0; i < n; i++) {
m[i] = matrix[i].slice();
m[i].push(constants[i]);
}
// 高斯消元，追踪主元列
var pivotCols = []; // 每行对应的主元列
var row = 0;
for (var col = 0; col < cols && row < n; col++) {
// 找最大主元
var maxRow = -1;
var maxVal = 1e-12;
for (var k = row; k < n; k++) {
if (Math.abs(m[k][col]) > maxVal) {
maxVal = Math.abs(m[k][col]);
maxRow = k;
}
}
if (maxRow === -1) continue; // 此列全为0，跳过（自由变量）
// 交换行
var temp = m[row]; m[row] = m[maxRow]; m[maxRow] = temp;
// 归一化主元行
var pivot = m[row][col];
for (var k = col; k <= cols; k++) m[row][k] /= pivot;
// 消去其他行
for (var k = 0; k < n; k++) {
if (k !== row) {
var factor = m[k][col];
for (var j = col; j <= cols; j++) m[k][j] -= factor * m[row][j];
}
}
pivotCols.push(col);
row++;
}
var rank = pivotCols.length;
