var MathEngine = {
solveLinearSystem: function (matrix, constants) {
var n = matrix.length;
if (n === 0) return [];
var cols = matrix[0].length;
// 构建增广矩阵 [A | b]
var m = [];
for (var i = 0; i < n; i++) {
