}
// 高斯消元，追踪主元列
var pivotCols = []; // 每行对应的主元列
var row = 0;
for (var col = 0; col < cols && row < n; col++) {
// 找最大主元
var maxRow = -1;
var maxVal = 1e-12;
for (var k = row; k < n; k++) {
if (Math.abs(m[k][col]) > maxVal) {
maxVal = Math.abs(m[k][col]);
maxRow = k;
}
}
if (maxRow === -1) continue; // 此列全为0，跳过（自由变量）
// 交换行
var temp = m[row]; m[row] = m[maxRow]; m[maxRow] = temp;
// 归一化主元行
var pivot = m[row][col];
for (var k = col; k <= cols; k++) m[row][k] /= pivot;
// 消去其他行
for (var k = 0; k < n; k++) {
