for (var i = rank; i < n; i++) {
if (Math.abs(m[i][cols]) > 1e-9) {
var excess = n - rank;
throw new Error("系统【超定】：约束存在冲突。请尝试至多添加" + excess + "个非边界物料。");
}
}
// 欠定：自由变量存在
if (rank < cols) {
throw new Error("系统【欠定】：自由度超出边界。请尝试至多减少" + (cols - rank) + "个非边界物料。");
}
// 唯一解：从增广矩阵读取结果
var res = new Array(cols);
for (var i = 0; i < rank; i++) {
