<div

(function () {
function fallbackCopy(text) {
var textarea = document.createElement('textarea');
textarea.value = text;
textarea.setAttribute('readonly', '');
textarea.style.position = 'fixed';
textarea.style.top = '-9999px';
document.body.appendChild(textarea);
textarea.select();
var success = false;
try {
success = document.execCommand('copy');
} catch (e) {
success = false;
}
document.body.removeChild(textarea);
return success;
}
function copyText(text) {
if (navigator.clipboard && navigator.clipboard.writeText) {
return navigator.clipboard.writeText(text).catch(function () {
return fallbackCopy(text)
? Promise.resolve()
: Promise.reject(new Error('Copy failed'));
});
}
return fallbackCopy(text)
? Promise.resolve()
: Promise.reject(new Error('Copy failed'));
}
function flashCopied(el) {
if (el._s2cbTimer) {
clearTimeout(el._s2cbTimer);
}
el.classList.add('s2cb-copied');
el._s2cbTimer = setTimeout(function () {
el.classList.remove('s2cb-copied');
el._s2cbTimer = null;
}, 1200);
}
function handleCopy(el) {
var text = el.textContent || '';
if (!text) {
return;
}
copyText(text).then(function () {
flashCopied(el);
}).catch(function () {
// 静默处理复制失败
});
}
document.addEventListener('click', function (event) {
var target = event.target.closest('.s2cb-copy');
if (!target) {
return;
}
var clickType = target.getAttribute('data-s2cb-click') || 'left';
if (clickType === 'left') {
event.preventDefault();
handleCopy(target);
}
});
document.addEventListener('contextmenu', function (event) {
var target = event.target.closest('.s2cb-copy');
if (!target) {
return;
}
var clickType = target.getAttribute('data-s2cb-click') || 'left';
if (clickType === 'right') {
event.preventDefault();
handleCopy(target);
}
});
})();
