";fromDate=" + fromDate + ";toDate=" + toDate;
$.when($.getJSON(pagesUrl), $.getJSON(siteUrl)).done(function (pagesRes, siteRes) {
var pagesData = pagesRes[0];
var siteData = siteRes[0];
if (pagesData.status !== "success" || siteData.status !== "success") {
container.innerHTML = "数据加载失败或格式不正确。";
return;
}
var siteTotal = 0;
for (var i = 0; i < siteData.message.length; i++) {
siteTotal += siteData.message[i].count;
}
var siteAvg = siteTotal / 30;
renderTable(pagesData.message, siteAvg);
}).fail(function () {
