function renderTable(list, siteAvg) {
var html = '<table class="wikitable sortable" style="width:100%">' +
'<thead><tr><th>排名</th><th>页面标题</th><th>日均浏览量（30日）</th><th>占比（30日）</th><th>累积占比</th></tr></thead><tbody>';
var cumPct = 0;
for (var i = 0; i < list.length; i++) {
var item = list[i];
var avg = item.count / 30;
var pct = siteAvg > 0 ? (avg / siteAvg * 100) : 0;
cumPct += pct;
var encodedTitle = encodeURIComponent(item.page_title.replace(/ /g, '_'));
html += '<tr>' +
'<td>' + (i + 1) + '</td>' +
'<td><a href="/wiki/' + encodedTitle + '">' + item.page_title + '</a></td>' +
'<td>' + avg.toFixed(2) + '</td>' +
'<td>' + pct.toFixed(2) + '%</td>' +
'<td>' + cumPct.toFixed(2) + '%</td>' +
'</tr>';
}
html += '</tbody></table>';
container.innerHTML = html;
mw.loader.using('jquery.tablesorter', function () {
$(container).find('table').tablesorter();
});
}
})();
