font-size: 11px;
color: #72777d;
line-height: 1.2;
}
.trh-tooltip-detail {
margin-top: 6px;
font-size: 11px;
color: #202122;
line-height: 1.35;
}
.trh-tooltip-meta {
margin-top: 7px;
display: flex;
flex-direction: column;
align-items: flex-start;
gap: 4px;
}
.trh-tooltip-meta-line {
display: inline-flex;
align-items: center;
min-height: 20px;
padding: 0 7px;
border: 1px solid transparent;
border-radius: 999px;
font-size: 11px;
line-height: 18px;
white-space: nowrap;
}
.trh-tooltip-meta-line.is-disabled {
border-color: #efc0c6;
background: #fff5f6;
color: #b32424;
}
.trh-tooltip-meta-line.is-cost {
border-color: #c9d7f7;
background: #f6f8ff;
color: #2a4b8d;
}
.trh-tooltip-detail-label {
color: #54595d;
margin-bottom: 4px;
}
.trh-tooltip-detail-value {
display: flex;
align-items: center;
gap: 6px;
flex-wrap: wrap;
}
.trh-tooltip-aspect {
display: inline-flex;
align-items: center;
gap: 4px;
}
.trh-tooltip-mini-icon {
width: 18px;
height: 18px;
image-rendering: pixelated;
flex: 0 0 18px;
}
.trh-tooltip-aspect-name {
color: #202122;
}
.trh-tooltip-plus {
color: #72777d;
}
.trh-tooltip-help-title {
font-size: 12px;
font-weight: 600;
color: #202122;
margin-bottom: 4px;
}
.trh-tooltip-help-body {
font-size: 11px;
color: #54595d;
line-height: 1.45;
}
@media (max-width: 992px) {
.trh-topbar {
align-items: flex-start;
flex-direction: row;
}
.trh-topbar-main {
width: 100%;
}
.trh-min-row {
align-items: center;
flex-direction: row;
flex-wrap: wrap;
}
.trh-body {
display: block;
}
.trh-area-select,
.trh-area-result {
max-width: 100%;
flex: 0 0 100%;
}
.trh-area-result {
border-left: 0;
border-top: 1px solid #dee2e6;
}
.trh-panel-select,
.trh-panel-result {
max-height: none;
overflow: visible;
}
.trh-chip-scroller {
max-height: 40vh;
overflow-y: auto;
padding-right: 10px;
}
.trh-result {
overflow: visible;
padding-right: 0;
}
.trh-slot-row {
flex-direction: column;
}
.trh-panel-result .trh-slot-row {
flex-direction: column;
}
.trh-section-head {
align-items: flex-start;
flex-direction: column;
}
.trh-section-controls {
align-items: center;
flex-direction: row;
flex-wrap: wrap;
width: 100%;
}
